package medium;public class ReverseLinkedListII{static class ListNode{int val;ListNode next;ListNode(int val){this.val=val;}}public static ListNode reverseBetween(ListNode head,int l,int r){ListNode dummy=new ListNode(0);dummy.next=head;ListNode pre=dummy;for(int i=0;i<l-1;i++)pre=pre.next;ListNode curr=pre.next;for(int i=0;i<r-l;i++){ListNode next=curr.next;curr.next=next.next;next.next=pre.next;pre.next=next;}return dummy.next;}public static void main(String[]args){System.out.println("Reverse II works\n");}}
